// Send Email (Supports Large Files via Multipart & GridFS)
router.post('/send', authenticateWebmail, upload.array('attachments'), async (req, res) => {
  try {
    const { to, cc, bcc, subject, htmlBody } = req.body;
    const sender = await Mailbox.findById(req.user.mailbox_id);
    const fromHeader = sender && (sender.first_name || sender.last_name) 
        ? `"${sender.first_name || ''} ${sender.last_name || ''}".trim() <${req.user.email}>`
        : req.user.email;

    const safeHtml = `<div style="font-family: sans-serif;">${htmlBody}</div>`;
    const plainText = htmlBody.replace(/<[^>]+>/g, ' ');

    const currentBucket = getBucket();
    if (!currentBucket) return res.status(503).json({ error: 'Database bucket not ready' });

    // Upload attachments to GridFS from Multer's memory buffers
    const processedAttachments = [];
    if (req.files && req.files.length > 0) {
        for (const file of req.files) {
            const uploadStream = currentBucket.openUploadStream(file.originalname, {
                contentType: file.mimetype
            });

            await new Promise((resolve, reject) => {
                const stream = new Readable();
                stream.push(file.buffer);
                stream.push(null);
                stream.pipe(uploadStream)
                    .on('finish', resolve)
                    .on('error', reject);
            });

            processedAttachments.push({
                filename: file.originalname,
                contentType: file.mimetype,
                gridfs_id: uploadStream.id,
                size: file.size
            });
        }
    }

    // Save to Sent
    await EmailMessage.create({
      mailbox_id: req.user.mailbox_id,
      direction: 'outbound',
      from: fromHeader,
      to, cc: cc || '', bcc: bcc || '',
      subject: subject || '',
      text_body: plainText,
      html_body: safeHtml,
      has_attachments: processedAttachments.length > 0,
      attachments: processedAttachments,
      folder: 'sent',
      is_read: true
    });

    const allRecipients = new Set([
        ...to.split(/[;,]+/).map(r => r.trim()).filter(r => r),
        ...(cc ? cc.split(/[;,]+/).map(r => r.trim()).filter(r => r) : []),
        ...(bcc ? bcc.split(/[;,]+/).map(r => r.trim()).filter(r => r) : [])
    ]);

    for (const recipientEmail of allRecipients) {
        await emailService.sendEmail(fromHeader, recipientEmail, subject, plainText, safeHtml, {
            cc, bcc, attachments: processedAttachments
        });
    }

    res.json({ message: 'Email sent successfully' });
  } catch (err) {
    logger.error('Send Error:', err);
    res.status(500).json({ error: 'Failed to send email' });
  }
});

module.exports = router;

const dns = require('dns').promises;
const nodemailer = require('nodemailer');
const mongoose = require('nodemailer');
const mongo = require('mongoose');
const Mailbox = require('../models/Mailbox');
const Domain = require('../models/Domain');
const EmailMessage = require('../models/EmailMessage');
const SystemConfig = require('../models/SystemConfig');
const logger = require('../config/logger');

let bucket;
const getBucket = () => {
    if (!bucket && mongo.connection.readyState === 1) {
        bucket = new mongo.mongo.GridFSBucket(mongo.connection.db, {
            bucketName: 'attachments'
        });
    }
    return bucket;
};

const extractEmail = (fullAddress) => {
    if (!fullAddress) return '';
    const match = fullAddress.match(/<([^>]+)>/);
    return (match ? match[1] : fullAddress).toLowerCase().trim();
};

const deliverExternal = async (senderEmail, recipientEmail, subject, text, html, options = {}) => {
  try {
    const cleanRecipient = extractEmail(recipientEmail);
    const recipientDomain = cleanRecipient.split('@')[1];
    const mxRecords = await dns.resolveMx(recipientDomain);
    const bestMx = mxRecords.sort((a, b) => a.priority - b.priority)[0].exchange;

    const currentBucket = getBucket();

    // Prepare attachments by streaming from GridFS if necessary
    const attachments = [];
    if (options.attachments) {
        for (const att of options.attachments) {
            if (att.gridfs_id && currentBucket) {
                attachments.push({
                    filename: att.filename,
                    content: currentBucket.openDownloadStream(att.gridfs_id),
                    contentType: att.contentType
                });
            } else if (att.content) {
                attachments.push(att);
            }
        }
    }

    const transporter = nodemailer.createTransport({ host: bestMx, port: 25, secure: false, tls: { rejectUnauthorized: false } });
    await transporter.sendMail({
      from: senderEmail, to: recipientEmail, cc: options.cc, bcc: options.bcc,
      subject, text, html, attachments
    });
    return true;
  } catch (error) {
    logger.error(`External Delivery Failed: ${error.message}`);
    return false;
  }
};

const sendEmail = async (from, to, subject, text, html, options = {}) => {
    try {
        const cleanTo = extractEmail(to);
        const recipientMailbox = await Mailbox.findOne({ email: cleanTo });
        if (recipientMailbox) {
            await EmailMessage.create({
                mailbox_id: recipientMailbox._id,
                direction: 'inbound',
                from, to: cleanTo, cc: options.cc || '', bcc: options.bcc || '',
                subject: subject || '', text_body: text || '', html_body: html || '',
                has_attachments: options.attachments && options.attachments.length > 0,
                attachments: options.attachments || [],
                folder: 'inbox', is_read: false
            });
            return true;
        } else {
            return await deliverExternal(from, to, subject, text, html, options);
        }
    } catch (err) {
        logger.error('Email Service Error:', err);
        return false;
    }
};

module.exports = { deliverExternal, sendEmail };

