        <div className="h-4 bg-slate-100 rounded-full w-3/4 mb-3"></div>
        <div className="h-2 bg-slate-50 rounded-full w-full"></div>
      </div>
    ))}
  </div>
);

const WebmailMessageList = (props: Props) => {
